<script setup lang="ts">
import { ref, watch } from 'vue';

const props = withDefaults(
  defineProps<{
    src: string | null;
    alt?: string;
    ratio?: string;
  }>(),
  { alt: '', ratio: '2 / 3' },
);

const loaded = ref(false);
const failed = ref(false);

// Reset load/error state when the source changes.
watch(
  () => props.src,
  () => {
    loaded.value = false;
    failed.value = false;
  },
);
</script>

<template>
  <div class="poster" :style="{ aspectRatio: ratio }">
    <img
      v-if="src && !failed"
      :src="src"
      :alt="alt"
      loading="lazy"
      decoding="async"
      class="poster__img"
      :class="{ 'is-loaded': loaded }"
      @load="loaded = true"
      @error="failed = true"
    />
    <div v-else class="poster__fallback" aria-hidden="true">
      <span>Далі&nbsp;Буде</span>
    </div>
  </div>
</template>

<style scoped>
.poster {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: var(--radius-media);
  background: linear-gradient(160deg, var(--surface-2), var(--surface));
  border: 1px solid var(--border);
}
.poster__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity var(--dur) var(--ease);
}
.poster__img.is-loaded {
  opacity: 1;
}
.poster__fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.75rem;
  letter-spacing: 0.04em;
  color: var(--text-faint);
  text-align: center;
  padding: var(--sp-2);
}
</style>
